/* The Blueprint — live GM workspace. */
let sidebarCollapsed=false,dashboardConference=null;
try{sidebarCollapsed=localStorage.getItem('hoops-sidebar-collapsed')==='true'}catch{}
const GM_ICONS={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2 M7 14h2 M15 14h2 M7 18h2 M15 18h2',trade:'M4 7h16 M4 7l4-4 M4 7l4 4 M20 17H4 M20 17l-4-4 M20 17l-4 4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',briefcase:'M8 6V3h8v3 M3 7h18v14H3Z M3 12h18 M10 12v3h4v-3',trophy:'M8 3h8v7a4 4 0 0 1-8 0Z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 14v6 M8 21h8',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',mail:'M3 5h18v14H3Z M3 5l9 7 9-7',menu:'M8 5l7 7-7 7',moon:'M20 14A8 8 0 0 1 10 4a9 9 0 1 0 10 10',exit:'M9 3H3v18h6 M10 12h11 M17 8l4 4-4 4'};
function gmIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${GM_ICONS[name]||GM_ICONS.home}"/></svg>`}
function toggleGMSidebar(){sidebarCollapsed=!sidebarCollapsed;try{localStorage.setItem('hoops-sidebar-collapsed',String(sidebarCollapsed))}catch{}render();document.getElementById('sidebar-toggle')?.focus()}
function gmInitials(){return(state.gmName||'General Manager').split(/\s+/).filter(Boolean).map(n=>n[0]).slice(0,2).join('').toUpperCase()}
function careerBodyContent(){if(!ownerCanManage())return ownerDismissal();if(view==='Attendance rankings')return gmAttendanceRankings();if(view==='Hall of Fame')return hallOfFameView();if(view==='GM Inbox')return gmInboxView();if(view==='Watch list')return watchListView();if(view==='Players')return playersView();if(view==='League history')return leagueHistoryView();if(view==='Settings')return settingsView();if(view==='Overview')return dashboardOverview();if(view==='Power rankings')return gmPowerRankings(true);if(view==='Team management')return teamManagementView();if(view==='Award races')return awardRacesView();if(view==='News feed')return newsFeedView();if(view==='Expansion')return expansionView();if(view==='Draft')return draftView();if(view==='Finances')return financesView();if(view==='GM Office')return gmOfficePage();if(view==='Roster')return roster();if(view==='Rotations')return rotationsView();if(view==='Schedule')return scheduleView();if(view==='Trades')return trades();if(view==='Free agency')return freeAgencyView();if(view==='Front office')return ownerPanel()+`<div class="gm-office-grid">${gmTasks()}${gmFinances()}${gmNotes()}</div>`;if(view==='Player stats')return leagueStatsView();if(view==='Team stats')return teamStatsView();if(view==='League stats')return leagueOverviewView();if(view==='Playoffs')return playoffsView();if(view==='Franchise history')return gmHistory();return standings()}
function renderCareerShell(){gmCheckEmployment();const sidebarScroll=document.querySelector('.gm-sidebar')?.scrollTop||0;const nav=[['GM Career','briefcase'],['Overview','home'],['News feed','mail'],['Roster','users'],['Players','users'],['Watch list','search'],['Rotations','users'],['Schedule','calendar'],['Trades','trade'],['Free agency','search'],['Front office','briefcase'],['Finances','briefcase'],['Team management','users'],['Standings','trophy'],['Player stats','history'],['Award races','trophy'],['Team stats','users'],['League stats','history'],['Playoffs','trophy'],['Draft','users'],['Expansion','users'],['Franchise history','history'],['League history','trophy'],['Hall of Fame','trophy'],['Settings','briefcase']];document.getElementById('app').innerHTML=`<div class="layout gm-shell ${sidebarCollapsed?'sidebar-collapsed':''}"><aside class="gm-sidebar"><button id="sidebar-toggle" class="sidebar-toggle" onclick="toggleGMSidebar()" aria-label="${sidebarCollapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!sidebarCollapsed}" aria-controls="gm-navigation">${gmIcon('menu')}</button><nav id="gm-navigation" aria-label="Franchise navigation">${nav.filter(([label])=>controlledTeamId()>=0||['GM Career','News feed','Roster','Players','Schedule','Standings','Player stats','Award races','Team stats','League stats','Playoffs','Franchise history','League history','Hall of Fame'].includes(label)).map(([label,icon])=>`<button class="${view===label?'active':''}" onclick="go('${label}')" title="${label}" aria-label="${label}" ${view===label?'aria-current="page"':''}>${gmIcon(icon)}<span class="gm-nav-label">${label}</span></button>`).join('')}</nav><div class="gm-sidebar-bottom"><button onclick="toggleCareerDark(!state.darkMode)" title="Toggle dark mode" aria-label="Toggle dark mode" aria-pressed="${!!state.darkMode}">${gmIcon('moon')}<span class="gm-nav-label">Dark mode</span></button><button onclick="returnToTitle()" title="Save and return to title" aria-label="Save and return to title">${gmIcon('exit')}<span class="gm-nav-label">Title screen</span></button></div></aside><main class="gm-main"><header class="gm-header"><div class="gm-header-title">GM DASHBOARD <span></span></div><div class="gm-season-label">${state.year} SEASON <i aria-hidden="true">|</i> <strong class="gm-phase">${seasonPhaseLabel()}</strong>${state.day<seasonLength()?'<span class="gm-season-day">DAY '+(state.day+1)+' / '+seasonLength()+'</span>':''}</div><button type="button" class="gm-user gm-office-link" onclick="go('GM Office')" aria-label="Open GM Office" aria-current="${view==='GM Office'?'page':'false'}"><span class="gm-avatar">${escapeHTML(gmInitials())}</span><div><strong>${escapeHTML(state.gmName||'General Manager')}</strong><small>GENERAL MANAGER</small></div></button><button class="gm-mail" onclick="openGMInbox()" aria-label="Open GM Inbox">${gmIcon('mail')}${gmInboxUnread()?'<span>'+gmInboxUnread()+'</span>':''}</button></header><div class="gm-workspace">${['Overview','Playoffs'].includes(view)?'':`<div class="gm-view-heading"><div><div class="eyebrow">${escapeHTML(state.leagueName||'BASKETBALL OPERATIONS')}</div><h1>${escapeHTML(view)}</h1></div>${state.day<seasonLength()&&gmCanAdvance()?advanceControls():''}</div>`}${careerContent()}<footer class="gm-footer"><span>${escapeHTML(controlledTeamId()<0?'GM Free Agency':team().city+' '+team().name)} <i>|</i> GM DASHBOARD</span><span id="save-status">${escapeHTML(notice||'Saved in this browser')}</span><span>BUILD / MANAGE / LEAVE A LEGACY</span></footer></div></main></div>`;document.querySelector('.gm-sidebar').scrollTop=sidebarScroll}
function gmPanel(title,body,extra='',classes=''){return `<section class="gm-panel ${classes}"><div class="gm-panel-heading"><h2>${title}</h2>${extra}</div>${body}</section>`}
function gmRecords(){return state.history.filter(h=>h.stage==='Regular season'&&(h.a===controlledTeamId()||h.b===controlledTeamId()))}
function gmStatValues(){const games=gmRecords(),n=games.length;if(!n)return {ppg:'—',opp:'—',rpg:'—',apg:'—',games:0};const totals=games.reduce((sum,h)=>{const own=h.box.filter(p=>p.team===team().abbr);sum.pts+=h.a===controlledTeamId()?h.sa:h.sb;sum.opp+=h.a===controlledTeamId()?h.sb:h.sa;sum.reb+=own.reduce((a,p)=>a+p.reb,0);sum.ast+=own.reduce((a,p)=>a+p.ast,0);return sum},{pts:0,opp:0,reb:0,ast:0});return{ppg:(totals.pts/n).toFixed(1),opp:(totals.opp/n).toFixed(1),rpg:(totals.reb/n).toFixed(1),apg:(totals.ast/n).toFixed(1),games:n}}
function gmTeamBanner(){const t=team(),conf=rank().filter(x=>x.conference===t.conference),position=conf.findIndex(x=>x.w===t.w&&x.l===t.l)+1,tied=conf.filter(x=>x.w===t.w&&x.l===t.l).length>1,ratingRank=state.teams.filter(x=>strength(x)>strength(t)).length+1;return `<section class="gm-team-banner"${cityPhotoBannerStyle(t,state.year)}><div class="gm-banner-logo">${teamLogo(t,true)}</div><div class="gm-team-identity"><div>${escapeHTML(t.city.toUpperCase())}</div><h1>${escapeHTML(t.name.toUpperCase())}</h1><strong>${t.w} – ${t.l}</strong><p>${tied?'T-':''}${position} in ${escapeHTML(t.conference)} Conference<br>${escapeHTML(t.division)} Division</p></div><div class="gm-banner-stats"><div><small>TEAM RATING</small><strong>${ratingMarkup(Math.round(strength(t)))}</strong><span>#${ratingRank} in league</span></div><div><small>CAP SPACE</small><strong>${money(salaryCap()-payroll())}</strong><span>of ${money(salaryCap())}</span></div><div><small>CHAMPIONSHIPS</small><strong>${gmFranchiseTitles(t)}</strong><span>Franchise history</span></div></div><div class="gm-banner-motto">A BETTER<br>TOMORROW.</div></section>`}
function gmNextGame(){const pair=next(),t=team();if(!pair){const done=state.day>=seasonLength();return gmPanel(done?'POSTSEASON':'NEXT GAME',`<div class="gm-next-empty"><h3>${done?(state.champion!==null?escapeHTML(state.teams[state.champion].city)+' are champions.':'The postseason awaits.'):'A night off.'}</h3><p>${done?'The qualifying teams compete for the championship.':'Your team has a bye. The rest of the league plays today.'}</p><button class="primary" onclick="${!done?'sim(1)':state.champion===null?'playoffs()':'newSeason()'}">${!done?'Advance day':state.champion===null?'Simulate playoffs':'Continue offseason'} →</button></div>`,'','gm-next-game')};const opp=state.teams[pair.find(id=>id!==controlledTeamId())];return gmPanel('NEXT GAME',`<div class="gm-matchup"><div class="gm-match-team">${teamLogo(t)}<strong>${escapeHTML(t.city)}<br>${escapeHTML(t.name)}</strong><small>${t.w} – ${t.l}</small></div><span class="gm-versus">VS</span><div class="gm-match-team">${teamLogo(opp)}<strong>${escapeHTML(opp.city)}<br>${escapeHTML(opp.name)}</strong><small>${opp.w} – ${opp.l}</small></div><div class="gm-match-detail"><strong>DAY ${state.day+1}</strong><p>${pair[0]===controlledTeamId()?'Home court':'On the road'}<br>${escapeHTML(teamArena(pair[0]===controlledTeamId()?t:opp))}</p><button class="primary" onclick="viewGMMatchup()">View matchup →</button></div></div>`,`<span>REGULAR SEASON</span>`,'gm-next-game')}

function gmTeamStats(){const v=gmStatValues();return gmPanel('TEAM STATS <small>THIS SEASON</small>',`<div class="gm-stat-strip">${[['PPG',v.ppg],['RPG',v.rpg],['APG',v.apg],['OPP PPG',v.opp]].map(([k,n])=>`<div><strong>${n}</strong><b>${k}</b></div>`).join('')}</div><div class="gm-stats-caption">${v.games?v.games+' regular-season games':'Stats appear after your first game.'}</div><div class="gm-handwritten">Right players.<br>Brighter future.</div>`,'','gm-stat-panel')}
function gmUpcoming(){const rows=state.schedule.map((r,i)=>({pair:r.find(p=>p.includes(controlledTeamId())),day:i+1})).filter(x=>x.day>state.day&&x.pair).slice(0,5);return gmPanel('UPCOMING GAMES',`<div class="gm-upcoming-list">${rows.map(({pair,day})=>{const opp=state.teams[pair.find(id=>id!==controlledTeamId())];return `<button onclick="go('Schedule')"><span>DAY ${day}</span>${teamLogo(opp)}<strong>${pair[0]===controlledTeamId()?'vs.':'@'} ${escapeHTML(opp.abbr)}</strong><small>${opp.w}–${opp.l}</small></button>`}).join('')||'<p class="gm-empty">Regular season complete.</p>'}</div>`,`<button onclick="go('Schedule')">View all</button>`,'gm-upcoming')}
function setDashboardConference(index){dashboardConference=[...new Set(state.teams.map(t=>t.conference))][index];render()}
function gmStandings(){const conferences=[...new Set(state.teams.map(t=>t.conference))],selected=conferences.includes(dashboardConference)?dashboardConference:team().conference,rows=rank().filter(t=>t.conference===selected),top=rows.slice(0,5);if(team().conference===selected&&!top.some(t=>t.id===controlledTeamId()))top.push(team());const leader=rows[0];return gmPanel('LEAGUE STANDINGS',`<div class="gm-conference-tabs">${conferences.map((c,i)=>`<button aria-pressed="${c===selected}" class="${c===selected?'active':''}" onclick="setDashboardConference(${i})">${escapeHTML(c)}</button>`).join('')}</div><div class="scroll"><table><thead><tr><th>#</th><th>Team</th><th>W</th><th>L</th><th>GB</th></tr></thead><tbody>${top.map(t=>`<tr class="${t.id===controlledTeamId()?'your-team':''}"><td>${rows.findIndex(x=>x.id===t.id)+1}</td><td>${escapeHTML(t.city+' '+t.name)}</td><td>${t.w}</td><td>${t.l}</td><td>${t.id===leader?.id?'—':((leader.w-t.w+t.l-leader.l)/2).toFixed(1)}</td></tr>`).join('')}</tbody></table></div><button class="gm-panel-link" onclick="go('Standings')">View full standings →</button>`,'','gm-standings')}
const GM_TASKS=[['Review starting lineup','Roster'],['Evaluate trade targets','Trades'],['Check available free agents','Free agency'],['Set your game plan','Roster']];
const GM_TASK_HELP=['Open your roster or rotations to review the starting lineup.','Select an incoming player in Trades to evaluate the target.','Open Free agency to review available players.','Apply a game plan or change its pace or approach.'];
function gmTaskFlags(){return state.dashboardTasksVersion===1?(state.dashboardTasks||[false,false,false,false]):[false,false,false,false]}
function completeGMTask(index){if(!ownerCanManage()||!Number.isInteger(index)||index<0||index>=GM_TASKS.length||gmTaskFlags()[index])return false;state.dashboardTasks=[...gmTaskFlags()];state.dashboardTasks[index]=true;state.dashboardTasksVersion=1;return true}
async function saveGMTask(index){const career=state,previous=state.dashboardTasks,version=state.dashboardTasksVersion;if(!completeGMTask(index))return;const updated=state.dashboardTasks;if(!await save()){if(state===career&&state.dashboardTasks===updated){state.dashboardTasks=previous;state.dashboardTasksVersion=version}toast('Task progress could not be saved.');}}
function openGMTask(index){if(!GM_TASKS[index])return;if(GM_TASKS[index][1]==='Roster')rosterTeamId=0;go(GM_TASKS[index][1])}

function gmTasks(){const done=gmTaskFlags(),remaining=GM_TASKS.filter((_,i)=>!done[i]).length;return gmPanel('FRONT OFFICE TASKS',`<div class="gm-task-list">${GM_TASKS.map(([label,target],i)=>`<div><label title="${GM_TASK_HELP[i]}"><input type="checkbox" ${done[i]?'checked':''} disabled aria-label="${label}: ${done[i]?'completed':'not completed'}"><span>${label}</span></label><button onclick="openGMTask(${i})" aria-label="${label}">↗</button></div>`).join('')}</div><button class="gm-panel-link" onclick="go('Front office')">Open front office →</button>`,`<span class="gm-count">${remaining}</span>`,'gm-tasks')}
function gmNews(){return gmPanel('RECENT NEWS',`<div class="gm-news-list">${state.news.slice(0,3).map((n,i)=>`<button onclick="showGMNews()"><span class="gm-news-icon">${gmIcon(i===0?'mail':'briefcase')}</span><span><strong>${escapeHTML(n)}</strong><small>${i===0?'Latest franchise update':'Front office wire'}</small></span></button>`).join('')||'<p class="gm-empty">No franchise updates yet.</p>'}</div>`,`<button onclick="showGMNews()">View all</button>`,'gm-news')}
function showGMNews(){go('News feed')}
function gmFinances(){return gmPanel('FINANCIAL OVERVIEW',`<div class="gm-finance-body"><div><div class="gm-cap-track" role="meter" aria-label="Salary cap used" aria-valuemin="0" aria-valuemax="${salaryCap()}" aria-valuenow="${Math.min(payroll(),salaryCap()).toFixed(1)}"><i style="width:${Math.min(100,payroll()/salaryCap()*100)}%"></i></div><dl><div><dt>Team payroll</dt><dd>${money(payroll())}</dd></div><div><dt>Salary cap</dt><dd>${money(salaryCap())}</dd></div><div><dt>Cap space</dt><dd>${money(salaryCap()-payroll())}</dd></div><div><dt>Roster spots</dt><dd>${team().roster.length} / 15</dd></div></dl></div><span class="gm-finance-note">Sustain.<br>Compete.<br>Build.</span></div>`,'','gm-finances')}
function gmDepth(){return gmPanel('DEPTH CHART <small>STARTING FIVE</small>',`<div class="scroll"><table><tbody>${team().roster.slice(0,5).map(p=>`<tr><td>${p.pos}</td><td><button class="namebutton" onclick="profile(${p.id})">${escapeHTML(p.name)}</button></td><td>${ratingMarkup(p.ovr)}</td><td>Starter</td></tr>`).join('')}</tbody></table></div>`,`<button onclick="go('Roster')">View roster</button>`,'gm-depth')}
function gmNotes(){return gmPanel('TEAM NOTES',`<form onsubmit="saveGMNotes(event)"><label class="sr-label" for="gm-notes">Team notes</label><textarea id="gm-notes" maxlength="1000" placeholder="Your plans for the roster, trades, and the season…">${escapeHTML(state.teamNotes||'')}</textarea><div><small>Private to this career</small><button type="submit">Save notes</button></div></form>`,'','gm-notes')}
function saveGMNotes(event){event.preventDefault();state.teamNotes=document.getElementById('gm-notes').value.slice(0,1000);save().then(ok=>{if(ok)toast('Team notes saved.')})}
let historyTeamId=0;
function openTeamHistory(id){if(!state.teams.some(t=>t.id===Number(id)))return;historyTeamId=Number(id);go('Franchise history')}
function gmHistory(){
 const t=state.teams.find(t=>t.id===historyTeamId)||team();
 return teamHistoryPage(t);
}
// Rank recorded regular-season arena occupancy; forecasts and unplayed teams are excluded.
function gmAttendanceSummary(club=team()){
 const rows=state.teams.filter(t=>!expansionPendingSeason(t)).map(t=>({id:t.id,plan:t.owner?.plan})).filter(r=>r.plan?.year===state.year&&r.plan.homeGames>0).map(r=>({id:r.id,games:r.plan.homeGames,percent:Math.round(r.plan.attendanceSum/r.plan.homeGames*1000)/10}));
 const own=rows.find(r=>r.id===club.id);
 if(!own)return {percent:null,rank:null,tied:false,games:0,ranked:rows.length};
 return {...own,rank:1+rows.filter(r=>r.percent>own.percent).length,tied:rows.some(r=>r.id!==club.id&&r.percent===own.percent),ranked:rows.length};
}
function gmAttendance(){
 const a=gmAttendanceSummary();
 return gmPanel('ATTENDANCE',`<div class="gm-stat-strip"><div><strong>${a.percent===null?'—':a.percent.toFixed(1)+'%'}</strong><b>AVG. SEATS FILLED</b></div><div><strong>${a.rank===null?'—':(a.tied?'T-':'#')+a.rank}</strong><b>LEAGUE RANK</b></div></div><p class="gm-stats-caption">${a.games?a.games+' tracked regular-season home '+(a.games===1?'game':'games')+' · Ranked among '+a.ranked+' teams with attendance data.':'Attendance and rank appear after your first tracked regular-season home game.'}</p><button class="gm-panel-link" onclick="go('Attendance rankings')">View full attendance rankings →</button>`);
}
let attendanceVenue='home';
function setAttendanceVenue(venue){attendanceVenue=venue==='road'?'road':'home';render()}
function attendanceRankingRows(venue='home'){
 const records=state.teams.flatMap(t=>{const s=state.finances?.[t.id]?.season;return s?.year===state.year?(s.attendance||[]).map(g=>({...g,home:t.id})):[]});
 const rows=state.teams.filter(t=>!expansionPendingSeason(t)).map(club=>{
  const games=records.filter(g=>g[venue==='road'?'away':'home']===club.id),home=gmAttendanceSummary(club),gp=venue==='home'?home.games:games.length;
  const percent=venue==='home'?home.percent:gp?Math.round(games.reduce((n,g)=>n+g.occupancy,0)/gp*1000)/10:null;
  return {club,gp,percent,average:gp&&games.length===gp?Math.round(games.reduce((n,g)=>n+g.fans,0)/gp):null};
 });
 return rows.map(r=>({...r,rank:r.percent===null?null:1+rows.filter(x=>x.percent!==null&&x.percent>r.percent).length,tied:r.percent!==null&&rows.some(x=>x.club.id!==r.club.id&&x.percent===r.percent)})).sort((a,b)=>(a.rank??Infinity)-(b.rank??Infinity)||a.club.city.localeCompare(b.club.city));
}
function gmAttendanceRankings(){
 const rows=attendanceRankingRows(attendanceVenue),fmt=n=>n===null?'—':n.toLocaleString();
 return gmPanel('LEAGUE ATTENDANCE',`<div class="gm-conference-tabs" aria-label="Attendance venue"><button onclick="setAttendanceVenue('home')" aria-pressed="${attendanceVenue==='home'}" class="${attendanceVenue==='home'?'active':''}">Home attendance</button><button onclick="setAttendanceVenue('road')" aria-pressed="${attendanceVenue==='road'}" class="${attendanceVenue==='road'?'active':''}">Road attendance</button></div><p class="gm-stats-caption">${state.year}–${state.year+1} · Regular season · Ranked by average percentage of seats filled. Road attendance measures crowds at the team's away games.</p><div class="scroll" tabindex="0" role="region" aria-label="League attendance rankings"><table><thead><tr><th scope="col">Rank</th><th scope="col">Team</th><th scope="col">Tracked games</th><th scope="col">Average crowd</th><th scope="col">Seats filled</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.club.id===team().id?'your-team':''}"><td>${r.rank===null?'—':(r.tied?'T-':'#')+r.rank}</td><th scope="row"><span style="display:flex;align-items:center;gap:12px;text-align:left">${teamLogo(r.club)}${escapeHTML(r.club.city+' '+r.club.name)}</span></th><td>${r.gp}</td><td>${fmt(r.average)}</td><td>${r.percent===null?'—':r.percent.toFixed(1)+'%'}</td></tr>`).join('')}</tbody></table></div><p class="gm-stats-caption">Home percentages include existing season attendance records. Crowd counts and road attendance are recorded from this update onward; unavailable historical figures show —. Teams without tracked games remain unranked.</p><button class="gm-panel-link" onclick="go('Overview')">Back to GM dashboard →</button>`);
}
function dashboardOverview(){return `${gmTeamBanner()}<div class="gm-dashboard-grid">${gmNextGame()}${gmTeamStats()}${gmUpcoming()}${gmStandings()}${gmPowerRankings()}${gmAttendance()}${gmTasks()}${gmNews()}${gmFinances()}${gmDepth()}${gmNotes()}</div>`}

// Derive the phase from existing career progress so older saves need no migration.
function seasonPhaseLabel(){
 if(state.champion!==null&&state.champion!==undefined)return 'Offseason';
 if(state.day>=seasonLength())return 'Playoffs';
 if(!state.day)return 'Pre-season';
 const {start,end}=seasonMilestones(),currentDay=state.day+1;
 if(currentDay>=start&&currentDay<=end)return 'All-Star Weekend';
 return 'Regular Season';
}

function currentFranchiseSeason(t){const games=state.history.filter(g=>g.stage!=='Regular season'&&(g.a===t.id||g.b===t.id));return {year:state.year,key:t.key,name:t.city+' '+t.name,w:t.w,l:t.l,playoffs:games.length>0,champion:state.champion===t.id}}
function franchiseHistoryRows(){
 const rows=[...(state.franchiseArchive||[])];
 // Older saves may have season records retained with the unchanged head coach.
 for(const t of state.teams)for(const r of coachFor(t).seasons||[]){if(r.year>=state.year||r.team!==t.abbr||rows.some(x=>x.year===r.year&&x.key===t.key))continue;rows.push({year:r.year,key:t.key,name:t.city+' '+t.name,w:r.w,l:r.l,playoffs:r.pw+r.pl>0,champion:(state.championsArchive||[]).some(x=>x.year===r.year&&x.name===t.city+' '+t.name)})}
 for(const t of state.teams){if(expansionPendingSeason(t))continue;const i=rows.findIndex(r=>r.year===state.year&&r.key===t.key),r=currentFranchiseSeason(t);if(i<0)rows.push(r);else rows[i]=r}return rows;
}
function archiveFranchiseSeason(){state.franchiseArchive=franchiseHistoryRows()}
function readFranchiseArchive(raw,bad){if(raw===undefined)return [];if(!Array.isArray(raw)||raw.length>243000)bad('invalid franchise history.');const seen=new Set();return raw.map(r=>{if(!r||!Number.isInteger(r.year)||r.year<1900||r.year>10000||typeof r.key!=='string'||r.key.length>80||!r.key||typeof r.name!=='string'||r.name.length>100||!r.name||!Number.isInteger(r.w)||r.w<0||r.w>120||!Number.isInteger(r.l)||r.l<0||r.l>120||typeof r.playoffs!=='boolean'||typeof r.champion!=='boolean'||seen.has(r.year+':'+r.key))bad('invalid franchise season.');seen.add(r.year+':'+r.key);return {year:r.year,key:r.key,name:r.name,w:r.w,l:r.l,playoffs:r.playoffs,champion:r.champion}})}
function teamHistoryPage(t){
 if(franchiseHistoryPage==='seasonDetail')return teamSeasonPage(t);
 const seasons=franchiseHistoryRows().filter(r=>r.key===t.key).sort((a,b)=>b.year-a.year),w=seasons.reduce((n,r)=>n+r.w,0),l=seasons.reduce((n,r)=>n+r.l,0),pct=(w,l)=>w+l?(w/(w+l)).toFixed(3).replace(/^0/,''):'—';
 const totals=[['Seasons',seasons.length],['Record',w+'–'+l],['W/L%',pct(w,l)],['Playoff appearances',seasons.filter(r=>r.playoffs).length],['Championships',seasons.filter(r=>r.champion).length]];
 const header='<div class="team-history-picker"><label for="history-team">Team history</label><select id="history-team" onchange="openTeamHistory(this.value)">'+state.teams.map(club=>'<option value="'+club.id+'" '+(club.id===t.id?'selected':'')+'>'+escapeHTML(club.city+' '+club.name)+'</option>').join('')+'</select></div><section class="gm-panel team-history-hero"><div class="team-history-identity">'+teamLogo(t)+'<div><div class="eyebrow">FRANCHISE HISTORY</div><h2>'+escapeHTML(t.city+' '+t.name)+'</h2><p>'+escapeHTML(t.conference+' Conference · '+t.division+' Division')+'</p></div><button onclick="rosterTeamId='+t.id+';go(\'Roster\')">View roster →</button></div><dl class="team-history-totals">'+totals.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl></section>';
 const navigation=franchiseHistoryNavigation();
 if(franchiseHistoryPage==='rivalries')return header+navigation+rivalriesPanel(t);
 if(franchiseHistoryPage==='leaders')return header+navigation+franchiseLeadersPanel(t);
 if(franchiseHistoryPage==='headToHead')return header+navigation+headToHeadPanel(t);
 const rows=seasons.map(r=>'<tr><th scope="row"><a class="season-history-link" href="#franchise-season-'+t.id+'-'+r.year+'" onclick="openFranchiseSeason('+t.id+','+r.year+');return false">'+r.year+'–'+String(r.year+1).slice(-2)+'</a>'+(r.year===state.year?' <small>Current</small>':'')+'</th><td>'+escapeHTML(r.name)+'</td><td>'+r.w+'</td><td>'+r.l+'</td><td>'+pct(r.w,r.l)+'</td><td>'+(r.playoffs?'Yes':r.year===state.year&&state.champion===null?'—':'No')+'</td><td>'+(r.champion?'Champion':'—')+'</td></tr>').join('');
 return header+navigation+gmPanel('SEASON-BY-SEASON RECORD','<div class="scroll" tabindex="0" role="region" aria-label="'+escapeHTML(t.city+' '+t.name)+' season history"><table class="franchise-history-table"><thead><tr>'+['Season','Team','W','L','W/L%','Playoffs','Championship'].map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div><p class="muted">Regular-season records. Seasons include the current season; playoff appearances count played postseasons. Earlier unrecorded seasons are unavailable.</p>');
}

function gmOfficeState(){
 const t=team(),o=ownerFor(t),p=o.plan,projection=ownerBusinessProjection(t,p);
 return {profile:{name:state.gmName||'General Manager',team:t.city+' '+t.name,teamId:t.id,league:state.leagueName||'Dynasty Basketball League',year:state.year,wins:t.w,losses:t.l,winPercent:t.w+t.l?100*t.w/(t.w+t.l):null,patience:o.patience,tasksDone:gmTaskFlags().filter(Boolean).length,tasksTotal:GM_TASKS.length},ownership:{name:OWNER_TYPES[o.type].name,description:OWNER_TYPES[o.type].description,adapted:!!p.adapted,goals:p.goals.map(g=>({label:ownerGoalLabel(t,g),progress:ownerGoalDisplay(t,g),status:g.status,penalty:g.weight,review:g.deadline===seasonLength()+1?'Postseason review':g.deadline===seasonLength()?'Season-end review':'Day '+g.deadline+' review'}))},business:{attendance:p.homeGames?p.attendanceSum/p.homeGames:null,homeGames:p.homeGames,revenue:p.revenue,costs:p.costs,profit:p.revenue-p.costs,merchandise:p.merch,ticketPrice:p.ticketPrice,nextAttendance:projection.attendance,payroll:payroll(),salaryCap:salaryCap()},future:[{title:'Scouting',description:'Prospect boards and scouting assignments.'},{title:'Analytics',description:'Custom reports and decision tools.'},{title:'Player development',description:'Individual training plans and progress reviews.'}]};
}
function gmOfficeOwnership(data){
 const o=data.ownership,c=ownerFor(team()).campaign,owner=ownerFor(team());
 const longTerm=owner.type==='tycoon'?'Build a dynasty: two titles by '+(c.startYear+3)+'. '+owner.history.filter(h=>h.year>=c.startYear&&h.title).length+' / 2 titles.':owner.type==='rebuilder'?'Turnaround: improve the baseline win rate by '+(15/82*100).toFixed(1)+' percentage points by '+(c.startYear+1)+'.':'Consistent contender: reach the playoffs each season from '+c.startYear+' through '+(c.startYear+2)+'.';
 return gmPanel('OWNERSHIP GOALS','<div class="office-owner-intro"><strong>'+escapeHTML(o.name)+'</strong><p>'+escapeHTML(o.description)+'</p><label>Owner patience <b>'+data.profile.patience+'%</b><meter min="0" max="100" value="'+data.profile.patience+'">'+data.profile.patience+'%</meter></label></div>'+(o.adapted?'<p class="owner-adjustment">Expectations adjusted following a major injury.</p>':'')+'<div class="office-goal-list">'+o.goals.map(g=>'<article><div><h3>'+escapeHTML(g.label)+'</h3><small>'+escapeHTML(g.review)+'</small></div><span class="owner-status '+g.status+'">'+escapeHTML(g.status==='pending'?String(g.progress):g.status.toUpperCase())+'</span><p>Missed target: <b>−'+g.penalty+' owner patience</b></p></article>').join('')+'</div><details class="office-long-term"><summary>Long-term ownership plan</summary><p>'+escapeHTML(longTerm)+'</p><p>Completed reviews: '+escapeHTML(c.settled.join(', ')||'None yet')+'</p></details>','','office-goals');
}
function gmOfficeBusiness(data){
 const b=data.business,stats=[['Attendance',b.attendance===null?'—':Math.round(b.attendance*100)+'%'],['Revenue',money(b.revenue)],['Costs',money(b.costs)],['Profit',money(b.profit)],['Merchandise',money(b.merchandise)],['Next-home forecast',Math.round(b.nextAttendance*100)+'%']];
 return gmPanel('FAN & BUSINESS','<div class="office-business-metrics">'+stats.map(([label,value])=>'<div><small>'+label+'</small><strong>'+value+'</strong></div>').join('')+'</div><form class="office-ticket-form" onsubmit="event.preventDefault();ownerTicketPrice(this.elements.ticketPrice.value)"><label for="office-ticket-price">Average ticket price <span>per seat</span></label><div><span>$</span><input id="office-ticket-price" name="ticketPrice" type="number" required min="37.5" max="150" step=".5" value="'+b.ticketPrice+'"><button class="primary" type="submit">Update price</button></div><small>$37.50–$150 · Price affects projected attendance.</small></form><div class="office-payroll"><span>Payroll / salary cap</span><strong>'+money(b.payroll)+' / '+money(b.salaryCap)+'</strong><meter min="0" max="'+Math.max(b.salaryCap,b.payroll)+'" value="'+b.payroll+'">'+money(b.payroll)+'</meter></div><p class="office-helper">'+b.homeGames+' tracked home games · 18,000-seat arena. Revenue and costs reflect the simulated business ledger.</p>','','office-business');
}
function gmOfficePage(){
 const data=gmOfficeState(),p=data.profile;
 const header=`<section class="gm-panel office-profile"><div class="office-profile-heading"><span class="gm-avatar office-avatar">${escapeHTML(gmInitials())}</span><div><div class="eyebrow">BASKETBALL OPERATIONS · ${p.year}</div><h2>${escapeHTML(p.name)}</h2><p>General Manager · ${escapeHTML(p.team)}</p><p>${escapeHTML(p.league)}</p></div>${teamLogo(team())}</div><div class="office-metrics">${[['Season record',p.wins+'–'+p.losses],['Win percentage',p.winPercent===null?'—':p.winPercent.toFixed(1)+'%'],['Owner patience',p.patience+'%'],['Office tasks',p.tasksDone+' / '+p.tasksTotal]].map(([k,v])=>'<div><small>'+k+'</small><strong>'+v+'</strong></div>').join('')}</div><div class="office-shortcuts"><button onclick="go('Roster')">Manage Roster →</button><button onclick="go('Trades')">Trade Desk →</button><button onclick="openCoachProfile(${p.teamId})">Head Coach →</button><button onclick="openTeamHistory(${p.teamId})">Franchise History →</button></div></section>`;
 return '<div class="office-dashboard">'+header+'<div class="office-main-grid">'+gmOfficeOwnership(data)+gmOfficeBusiness(data)+'</div><div class="office-work-grid">'+gmTasks()+gmNotes()+'</div><section class="office-future-grid" aria-label="Future office tools">'+data.future.map(panel=>'<article class="gm-panel"><span class="office-coming">Planned</span><h3>'+panel.title+'</h3><p>'+panel.description+'</p></article>').join('')+'</section></div>';
}

// Calendar navigation delegates every simulated day to the existing engine.
function advanceDateValue(day){return scheduleDate(day).toISOString().slice(0,10)}
function advanceTarget(kind,value){
 const current=state.day,end=seasonLength(),m=seasonMilestones();
 if(kind==='day')return Math.min(end,current+1);
 if(kind==='week')return Math.min(end,current+7);
 if(kind==='playoffs')return end;
 if(kind==='deadline')return Math.max(0,m.deadline-1);
 if(kind==='allstar')return Math.max(0,m.start-1);
 let date;
 if(kind==='month'){
  date=scheduleDate(current+1);const day=date.getUTCDate();
  date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()+1);
  const last=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();
  date.setUTCDate(Math.min(day,last));
 }else if(kind==='date'){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return null;
  date=new Date(value+'T00:00:00Z');
  if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==value)return null;
 }else return null;
 const target=Math.round((date-scheduleDate(1))/86400000);
 if(kind==='date'&&(target<=current||target>end))return null;
 return Math.min(end,target);
}
function advanceCalendar(kind,value){
 if(!gmCanAdvance())return toast('Your employment has ended.');
 const target=advanceTarget(kind,value);
 if(target===null||target<=state.day)return toast('Choose a future date within this season.');
 document.querySelectorAll('.advance-menu[open]').forEach(el=>el.removeAttribute('open'));
 return sim(target-state.day);
}
function advanceControls(){
 const end=seasonLength();if(state.day>=end||!gmCanAdvance())return '';
 const options=[['day','Advance day'],['week','Advance week'],['month','Advance month'],['deadline','Advance to trade deadline'],['allstar','Advance to All-Star weekend'],['playoffs','Advance to playoffs']];
 return '<details class="advance-menu"><summary class="primary">Advance day <span aria-hidden="true">▾</span></summary><div class="advance-options">'+options.map(([key,label])=>'<button type="button" onclick="advanceCalendar(\''+key+'\')" '+(advanceTarget(key)<=state.day?'disabled':'')+'>'+label+'</button>').join('')+'<form onsubmit="event.preventDefault();advanceCalendar(\'date\',this.elements.advanceDate.value)"><label>Advance to date<input type="date" name="advanceDate" required min="'+advanceDateValue(state.day+2)+'" max="'+advanceDateValue(end+1)+'" value="'+advanceDateValue(Math.min(end+1,state.day+2))+'"></label><button type="submit" class="primary">Advance →</button></form><small>Stops before games on the selected date. The trade deadline option leaves time to make trades.</small></div></details>';
}
document.addEventListener('click',event=>{document.querySelectorAll('.advance-menu[open]').forEach(el=>{if(!el.contains(event.target))el.removeAttribute('open')})});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.advance-menu[open]').forEach(el=>{el.removeAttribute('open');el.querySelector('summary')?.focus()})});

function careerContent(){const body=careerBodyContent();return ['Draft','Playoffs'].includes(view)&&gmCanAdvance()?body:pageHeaderFor(view)+body}
